-- A Contact's dates by their keys (ADR 0126): one row per date it holds, its birthday and each
-- Custom field value that is a date, which the date scheduler's band reads on the indexes of month
-- and day (a yearly date) and of the date (a once date). The table is new and empty, so its indexes
-- are built with it. The contacts module writes the rows with each Contact from here on; a Contact
-- written before holds none until its next write (the project has no deployment to backfill).
-- create "contact_dates" table
CREATE TABLE "contact_dates" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying NOT NULL, "key" character varying NOT NULL, "date" date NOT NULL, "month_day" smallint NOT NULL, "contact_id" bigint NOT NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "contact_dates_contacts_dates" FOREIGN KEY ("workspace_id", "contact_id") REFERENCES "contacts" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "contact_dates_workspaces_contact_dates" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "contact_dates_key_check" CHECK (((kind)::text = 'birthday'::text) = ((key)::text = ''::text)), CONSTRAINT "contact_dates_kind_check" CHECK ((kind)::text = ANY ((ARRAY['birthday'::character varying, 'customField'::character varying])::text[])), CONSTRAINT "contact_dates_month_day_check" CHECK ((month_day)::numeric = ((EXTRACT(month FROM date) * (100)::numeric) + EXTRACT(day FROM date))));
-- create index "contact_dates_field_contact" to table: "contact_dates"
CREATE UNIQUE INDEX "contact_dates_field_contact" ON "contact_dates" ("workspace_id", "kind", "key", "contact_id");
-- create index "contactdate_workspace_id_contact_id" to table: "contact_dates"
CREATE INDEX "contactdate_workspace_id_contact_id" ON "contact_dates" ("workspace_id", "contact_id");
-- create index "contactdate_workspace_id_kind_key_date" to table: "contact_dates"
CREATE INDEX "contactdate_workspace_id_kind_key_date" ON "contact_dates" ("workspace_id", "kind", "key", "date");
-- create index "contactdate_workspace_id_kind_key_month_day" to table: "contact_dates"
CREATE INDEX "contactdate_workspace_id_kind_key_month_day" ON "contact_dates" ("workspace_id", "kind", "key", "month_day");

